def count_good_integers(num1, num2, min_sum, max_sum):
    MOD = 10**9 + 7

    def digit_sum(n):
        return sum(int(digit) for digit in str(n))

    count = 0
    for i in range(int(num1), int(num2) + 1):
        if min_sum <= digit_sum(i) <= max_sum:
            count += 1
            count %= MOD
