def colorTheArray(n, queries):
    nums = [0] * n
    answer = [0] * len(queries)

    for i, (index, color) in enumerate(queries):
        nums[index] = color

        if index > 0 and nums[index] == nums[index - 1]:
            answer[i] += 1
        if index < n - 1 and nums[index] == nums[index + 1]:
            answer[i] += 1

    return answer

def sum_of_powers(nums):
    MOD = 10**9 + 7
    nums.sort()
    n = len(nums)
    prefix_sum = [0] * (n + 1)
    for i in range(n):
        prefix_sum[i + 1] = (prefix_sum[i] + nums[i]) % MOD
    total_sum = 0
    for i in range(n):
        for j in range(i, n):
            total_sum = (total_sum + pow(nums[i], 2, MOD) * pow(nums[j], 2, MOD) * nums[i]) % MOD
    return total_sum

def minCost(cost, time):
    n = len(cost)
    dp = [[0 for _ in range(n)] for _ in range(n)]

    for i in range(n):
        dp[i][0] = cost[i]

    for i in range(1, n):
        for j in range(i):
            if time[i] >= time[j] + 1:
                dp[i][i] = min(dp[i][i], dp[j][i-1] + cost[i])
            else:
                dp[i][i] = min(dp[i][i], dp[j][i-1])

    return min(dp[n-1][i] for i in range(n))

from math import gcd
from collections import defaultdict

def isPossible(nums):
    graph = defaultdict(list)
    for i in range(len(nums)):
        for j in range(i+1, len(nums)):
            if gcd(nums[i], nums[j]) > 1:
                graph[i].append(j)
                graph[j].append(i)
    visited = [False] * len(nums)
    def dfs(node):
        visited[node] = True
        for neighbor in graph[node]:
            if not visited[neighbor]:
                dfs(neighbor)
    for i in range(len(nums)):
        if not visited[i]:
            dfs(i)
    return all(visited)

def minOperations(num1, num2):
    if num1 < 0:
        return -1

    operations = 0
    while num1 > 0:
        if num2 >= num1:
            return -1
        num1 -= (1 << (num2 + 1))
        operations += 1

    return operations

def specialPermutation(nums):
    MOD = 10**9 + 7
    n = len(nums)
    dp = [[0]*n for _ in range(1<<n)]
    for i in range(n):
        dp[1<<i][i] = 1
    for mask in range(1<<n):
        for i in range(n):
            if mask & (1<<i):
                for j in range(n):
                    if mask & (1<<j) and (nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0):
                        dp[mask][i] = (dp[mask][i] + dp[mask ^ (1<<i)][j]) % MOD
    return sum(dp[(1<<n) - 1][i] for i in range(n)) % MOD

