def waysToSplitArray(nums):
    MOD = 10**9 + 7
    count = 0
    zero_count = 0
    for num in nums:
        if num == 1:
            count += 1
        else:
            zero_count += 1
        if zero_count > 1:
            count = 0
            zero_count = 0
    return count % MOD

def numberOfWays(n, x):
    MOD = 10**9 + 7
    dp = [0] * (n + 1)
    dp[0] = 1
    for i in range(1, n + 1):
        for j in range(1, i + 1):
            if i - j**x >= 0:
                dp[i] = (dp[i] + dp[i - j**x]) % MOD
    return dp[n]

MOD = 10**9 + 7

def countSteppingNumbers(low, high):
    def countSteppingNumbers(n, low, high):
        if n == 0:
            return 1
        if n < 0 or n > len(high):
            return 0

        count = 0
        for i in range(n):
            if low[i] <= high[i] and (low[i] == high[i] or abs(low[i] - high[i]) == 1):
                count += countSteppingNumbers(n-1, low, high)
                count %= MOD
        return count

    return countSteppingNumbers(len(high), low, high)

def maximizeTheProfit(n, offers):
    dp = [0] * (n + 1)
    for start, end, gold in offers:
        for i in range(start, end + 1):
            dp[i] = max(dp[i], dp[start - 1] + gold)
    return dp[n - 1]

def furthest_point(moves):
    count_L = moves.count('L')
