def minOperations(nums, target):
    operations = 0
    while target > 0:
        found = False
        for i in range(len(nums)):
            if nums[i] > target:
                break
            if target >= nums[i]:
                target -= nums[i]
                nums.append(nums[i] // 2)
                nums.append(nums[i] // 2)
                operations += 1
                found = True
                break
        if not found:
            return -1
    return operations

def product_matrix(grid):
    n, m = len(grid), len(grid[0])
    p = [[1]*m for _ in range(n)]

    # Calculate the prefix product for each row
    for i in range(n):
        prefix_product = 1
        for j in range(m):
            p[i][j] = prefix_product
            prefix_product = (prefix_product * grid[i][j]) % 12345

    # Calculate the suffix product for each row
    for i in range(n):
        suffix_product = 1
        for j in range(m-1, -1, -1):
            p[i][j] = (p[i][j] * suffix_product) % 12345
            suffix_product = (suffix_product * grid[i][j]) % 12345

    return p

def minOperations(nums, k):
    collected = set()
    operations = 0
    for num in reversed(nums):
        collected.add(num)
        if len(collected) == k:
            operations += 1
            collected.remove(nums[operations])
