    sum1, sum2 = sum(nums1), sum(nums2)
    if sum1 == sum2:
        return sum1

    if sum1 < sum2:
        diff = sum2 - sum1
        for i in range(len(nums1)):
            if nums1[i] == 0:
                nums1[i] = diff
                break
    else:
        diff = sum1 - sum2
        for i in range(len(nums2)):
            if nums2[i] == 0:
                nums2[i] = diff
