def longest_special_substring(s):
    n = len(s)
    count = {}
    for i in range(n):
        for j in range(i+1, n+1):
            substr = s[i:j]
            if substr == substr[::-1]:
                count[substr] = count.get(substr, 0) + 1
    max_len = -1
    for substr, freq in count.items():
        if freq >= 3:
            max_len = max(max_len, len(substr))
    return max_len

