import heapq

def max_candies(H, W, T, grid):
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    start = None
    goal = None
    candies = []

    for i in range(H):
        for j in range(W):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'G':
                goal = (i, j)
            elif grid[i][j] == 'o':
                candies.append((i, j))

    if start is None or goal is None:
        return -1

    pq = [(0, start[0], start[1], 0)]
    visited = set()

    while pq:
        moves, x, y, candies_count = heapq.heappop(pq)

        if (x, y) == goal:
            return candies_count

        if (x, y, moves) in visited:
            continue

        visited.add((x, y, moves))

        for dx, dy in directions:
            nx, ny = x + dx, y + dy

            if 0 <= nx < H and 0 <= ny < W and grid[nx][ny] != '#':
                new_moves = moves + 1
                if new_moves > T:
                    continue

                if grid[nx][ny] == 'o':
                    new_candies_count = candies_count + 1
                else:
                    new_candies_count = candies_count

                heapq.heappush(pq, (new_moves, nx, ny, new_candies_count))

    return -1

