MOD = 998244353

def count_non_ddos_strings(s):
    n = len(s)
    dp = [[0]*52 for _ in range(n+1)]
    dp[0][0] = 1

    for i in range(n):
        for j in range(52):
            dp[i+1][j] = dp[i][j]
            if s[i] == '?':
                for k in range(52):
                    dp[i+1][k] = (dp[i+1][k] + dp[i][j]) % MOD
            else:
                if s[i].isupper():
                    dp[i+1][ord(s[i]) - ord('A') + ord('A')] = (dp[i+1][ord(s[i]) - ord('A') + ord('A')] + dp[i][j]) % MOD
                else:
                    dp[i+1][ord(s[i]) - ord('a') + ord('A')] = (dp[i+1][ord(s[i]) - ord('a') + ord('A')] + dp[i][j]) % MOD

    return sum(dp[n]) % MOD

