def find_conforming_set(H, W, S):
    # Initialize the grid with empty cells
    grid = [['.' for _ in range(W)] for _ in range(H)]

    # Fill the grid with the given letters
    for i in range(H):
        for j in range(W):
            grid[i][j] = S[i][j]

    # Function to check if a set of cells is valid
    def is_valid_set(A1, A2, A3, A4, A5):
        # Check if all cells have the correct letters
        if grid[A1[0]][A1[1]] != 's' or grid[A2[0]][A2[1]] != 'n' or grid[A3[0]][A3[1]] != 'u' or grid[A4[0]][A4[1]] != 'k' or grid[A5[0]][A5[1]] != 'e':
            return False

        # Check if cells are contiguous
        for i in range(4):
            if not (abs(A1[0] - A2[0]) == 1 and abs(A1[1] - A2[1]) == 1 or
                    abs(A2[0] - A3[0]) == 1 and abs(A2[1] - A3[1]) == 1 or
                    abs(A3[0] - A4[0]) == 1 and abs(A3[1] - A4[1]) == 1 or
                    abs(A4[0] - A5[0]) == 1 and abs(A4[1] - A5[1]) == 1):
                return False

        # Check if centers are on a common line
        x1, y1 = A1
        x2, y2 = A2
        x3, y3 = A3
        x4, y4 = A4
        x5, y5 = A5

        # Check if the line is horizontal or vertical
        if (x1 == x2 and x2 == x3 and x3 == x4 and x4 == x5) or (y1 == y2 and y2 == y3 and y3 == y4 and y4 == y5):
            return True

        # Check if the line is diagonal
        if (x1 == x2 and x2 == x3 and x3 == x4 and x4 == x5) or (y1 == y2 and y2 == y3 and y3 == y4 and y4 == y5):
            return True

        return False

    # Iterate over all possible sets of cells
    for i in range(H):
        for j in range(W):
            for k in range(W):
                for l in range(W):
                    for m in range(W):
                        for n in range(W):
                            for o in range(W):
                                for p in range(W):
                                    if is_valid_set((i, j), (i, k), (i, l), (i, m), (i, n)):
                                        return (i+1, j+1), (i+1, k+1), (i+1, l+1), (i+1, m+1), (i+1, n+1)

    return None

