def can_complete_moves(N, M, H, K, S, items):
    x, y = 0, 0
    health = H
    for i in range(N):
        if health < K:
            if (x, y) in items:
                health = K
        if S[i] == 'R':
            x += 1
        elif S[i] == 'L':
            x -= 1
        elif S[i] == 'U':
            y += 1
        elif S[i] == 'D':
            y -= 1
        if health < 0:
            return "No"
    return "Yes"

