import math

def is_infected(N, D, points):
    infected = [False] * N
    infected[0] = True

    for i in range(N):
        if infected[i]:
            for j in range(i+1, N):
                if math.sqrt((points[i][0] - points[j][0])**2 + (points[i][1] - points[j][1])**2) <= D:
                    infected[j] = True
                    break

    return infected

def main():
    import sys
    input = sys.stdin.read().split()
    N = int(input[0])
    D = int(input[1])
    points = [(int(input[2+2*i]), int(input[3+2*i])) for i in range(N)]

    infected = is_infected(N, D, points)
    for i in range(N):
        print("Yes" if infected[i] else "No")

if __name__ == "__main__":
    main()

