import sys

def solve():
    N = int(sys.stdin.readline())
    A = list(map(int, sys.stdin.readline().split()))
    Q = int(sys.stdin.readline())
    queries = [tuple(map(int, sys.stdin.readline().split())) for _ in range(Q)]

    sleep_sessions = []
    for i in range(1, N, 2):
        sleep_sessions.append((A[i], A[i+1]))

    sleep_sessions.sort()

    answers = []
    for l, r in queries:
        total_sleep = 0
        for start, end in sleep_sessions:
            if start <= l and end >= r:
                total_sleep += end - start
            else:
                break
        answers.append(total_sleep)

    for answer in answers:
        print(answer)

