def max_tastiness(N, courses):
    dp = [0] * (N + 1)
    dp[0] = 0
    dp[1] = courses[0][1]
    for i in range(2, N + 1):
        if courses[i - 1][0] == 0:
            dp[i] = max(dp[i - 1] + courses[i - 1][1], dp[i - 1])
        else:
            dp[i] = max(dp[i - 1] + courses[i - 1][1], dp[i - 1])
    return dp[N]

