def can_achieve_goal(H_A, W_A, A, H_B, W_B, B, H_X, W_X, X):
    # Generate all possible positions to paste A and B on C
    def generate_paste_positions(H, W):
        positions = []
        for i in range(H):
            for j in range(W):
                positions.append((i, j))
        return positions

    # Generate all possible positions to cut out a H_X x W_X area from C
    def generate_cut_positions(H, W):
        positions = []
        for i in range(H - H_X + 1):
            for j in range(W - W_X + 1):
                positions.append((i, j))
        return positions

    # Check if the cut-out sheet matches X
    def check_cut_out(positions, X):
        for i in range(H_X):
            for j in range(W_X):
                if X[i][j] == '#' and not any(A[p[0]][p[1]] == '#' for p in positions):
                    return False
                if X[i][j] == '.' and any(A[p[0]][p[1]] == '#' for p in positions):
                    return False
        return True

