def is_path(H, W, grid):
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    visited = [[False]*W for _ in range(H)]

    def dfs(i, j, prev_char):
        if i == H-1 and j == W-1:
            return True
        visited[i][j] = True
        for dx, dy in directions:
            ni, nj = i + dx, j + dy
            if 0 <= ni < H and 0 <= nj < W and not visited[ni][nj] and grid[ni][nj] == prev_char:
                if dfs(ni, nj, prev_char):
                    return True
        return False

    return dfs(0, 0, grid[0][0])

