    for i in range(N + 1):
        dp[i][0] = 1
    for i in range(1, N + 1):
        for j in range(1, X + 1):
            dp[i][j] = (dp[i - 1][j] + dp[i][j - T[i - 1]]) % MOD
    return dp[N][X]

