def find(parent, i):
    if parent[i] == i:
        return i
    else:
        return find(parent, parent[i])

def union(parent, rank, x, y):
    xroot = find(parent, x)
    yroot = find(parent, y)

    if rank[xroot] < rank[yroot]:
        parent[xroot] = yroot
    elif rank[xroot] > rank[yroot]:
        parent[yroot] = xroot
    else:
        parent[yroot] = xroot
        rank[xroot] += 1

def kruskal(N, edges, K):
    edges.sort(key=lambda x: x[2])
    parent = list(range(N))
    rank = [0]*N
    mst_cost = 0
    for u, v, w in edges:
        x = find(parent, u)
        y = find(parent, v)
        if x != y:
            union(parent, rank, x, y)
            mst_cost = (mst_cost + w) % K
    return mst_cost

