import sys

def solve(N, M, edges):
    INF = sys.maxsize
    dp = [[INF] * (1 << N) for _ in range(N)]
    dp[0][1] = 0

    for mask in range(1 << N):
        for u in range(N):
            if mask & (1 << u):
                for v, w in edges:
                    if mask & (1 << v):
                        dp[u][mask] = min(dp[u][mask], dp[v][mask ^ (1 << u)] + w)

    for mask in range(1 << N):
        if dp[0][mask] != INF:
            return dp[0][mask]

    return "No"

