    def is_valid(x, y):
        return 0 <= x < H and 0 <= y < W and grid[x][y] == '.'

    # Function to move in a given direction
    def move(x, y, direction):
        return (x + directions[direction][0], y + directions[direction][1])

    # BFS to find all possible positions
    from collections import deque
    queue = deque(start_positions)
    visited = set(start_positions)

    while queue:
        x, y = queue.popleft()
        for _ in range(N):
            for direction in ['L', 'R', 'U', 'D']:
                nx, ny = move(x, y, direction)
                if is_valid(nx, ny) and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    queue.append((nx, ny))

    return len(visited)

