import sys
import heapq

def main():
    N, M = map(int, sys.stdin.readline().split())
    graph = [[] for _ in range(N)]
    for _ in range(M):
        l, d, k, c, A, B = map(int, sys.stdin.readline().split())
        for i in range(k):
            graph[A-1].append((B-1, l + i*d, l + (i+1)*d, c))

    # Initialize the latest arrival time for each station
    latest_arrival = [-float('inf')] * N
    latest_arrival[0] = 0

    # Use a priority queue to process the stations
    pq = [(-float('inf'), 0)]

    while pq:
        current_time, station = heapq.heappop(pq)
        current_time = -current_time

        if current_time < latest_arrival[station]:
            continue

        for next_station, departure_time, arrival_time, travel_time in graph[station]:
            if departure_time <= current_time:
                new_time = departure_time + travel_time
                if new_time > latest_arrival[next_station]:
                    latest_arrival[next_station] = new_time
                    heapq.heappush(pq, (-new_time, next_station))

    for i in range(1, N):
        if latest_arrival[i] == -float('inf'):
            print("Unreachable")
        else:
            print(latest_arrival[i])

