class Node:
    def __init__(self, data):
        self.data = data
        self.next = None
        self.prev = None

class DoublyLinkedList:
    def __init__(self):
        self.head = None
        self.tail = None

    def insert_after(self, x, y):
        if x is None:
            return
        if x == self.tail:
            self.tail = Node(y)
        else:
            new_node = Node(y)
            new_node.next = x.next
            new_node.prev = x
            x.next.prev = new_node
            x.next = new_node
        self.tail = new_node

    def remove(self, x):
        if x is None:
            return
        if x == self.head:
            self.head = x.next
        else:
            x.prev.next = x.next
            x.next.prev = x.prev
        if x == self.tail:
            self.tail = x.prev

def process_queries(N, A, Q, queries):
    dll = DoublyLinkedList()
    for i in range(N):
        dll.insert_after(None, A[i])
    for query in queries:
        if query[0] == 1:
            dll.insert_after(dll.head, query[1])
        elif query[0] == 2:
            dll.remove(dll.head)
    result = []
    while dll.head is not None:
        result.append(dll.head.data)
        dll.head = dll.head.next
    return result

