    def check_win(grid):
        for i in range(3):
            if grid[i][0] == grid[i][1] == grid[i][2]:
                return True
            if grid[0][i] == grid[1][i] == grid[2][i]:
                return True
            if grid[0][0] == grid[1][1] == grid[2][2]:
                return True
            if grid[0][2] == grid[1][1] == grid[2][0]:
                return True
        return False

    # Check if there are white cells left
    def check_remaining_cells(grid):
        for i in range(3):
            for j in range(3):
                if grid[i][j] == 0:
                    return False
        return True

    # Simulate the game
    grid = [[0]*3 for _ in range(3)]
    score_takahashi = 0
    score_aoki = 0
    turn = 0
    while True:
        # Takahashi's turn
        if turn % 2 == 0:
            for i in range(3):
                for j in range(3):
                    if grid[i][j] == 0:
                        grid[i][j] = 1
                        score_takahashi += grid[i][j]
                        if check_win(grid):
                            return "Takahashi"
                        grid[i][j] = 0
        # Aoki's turn
        else:
            for i in range(3):
                for j in range(3):
                    if grid[i][j] == 0:
                        grid[i][j] = -1
                        score_aoki += grid[i][j]
                        if check_win(grid):
                            return "Aoki"
                        grid[i][j] = 0
        turn += 1

    # If no white cells remain, the player with the higher total score wins
    if check_remaining_cells(grid):
        return "Takahashi" if score_takahashi > score_aoki else "Aoki"
    else:
        return "Takahashi" if score_takahashi > score_aoki else "Aoki"

