def calculate_black_area(A, B, C, D):
    # Calculate the number of black regions in the rectangle
    black_count = 0
    for x in range(A, C):
        for y in range(B, D):
            if (x + y) % 2 == 0:
                black_count += 1
    return 2 * black_count

A, B, C, D = map(int, input().split())
print(calculate_black_area(A, B, C, D))

import sys

def ask_question(i, j):
    print(f"? {i} {j}")
    sys.stdout.flush()
    return int(input())

def find_remainder(N, L, R):
    low, high = L, R
    while low < high:
        mid = (low + high) // 2
        mid_pow = 2 ** (mid // N)
        if mid_pow * (mid_pow + 1) <= 2 ** N:
            mid_pow += 1

        left_sum = ask_question(mid_pow, 0)
        right_sum = ask_question(mid_pow, mid_pow - 1)

        if left_sum % 100 == right_sum % 100:
            high = mid
        else:
            low = mid + 1

    return ask_question(low, low)

N, L, R = map(int, sys.stdin.readline().split())
remainder = find_remainder(N, L, R)
print(f"! {remainder}")

def find_bingo_turn(N, T, A):
    grid = [[0]*N for _ in range(N)]
    for i in range(N):
        for j in range(N):
            grid[i][j] = N * (i-1) + j + 1

    for i in range(T):
        for j in range(N):
            if grid[j][i] == A[i]:
                return i + 1

    return -1

