A = list(map(int, input().split()))
print(find_bingo_turn(N, T, A))

def find_culprit(A, B):
    suspects = [1, 2, 3]
    if A in suspects and B in suspects:
        if A == B:
            return -1
        else:
            return suspects.index(A) + 1
    else:
        return -1

