def has_palindrome_substring(s):
    for i in range(len(s)-1):
        if s[i:i+2] == s[::-1][i:i+2]:
            return True
    return False

def is_prime(n):
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def max_prime_distance(nums):
    prime_indices = [i for i, num in enumerate(nums) if is_prime(num)]
    max_distance = 0
    for i in range(len(prime_indices)):
        for j in range(i + 1, len(prime_indices)):
            max_distance = max(max_distance, prime_indices[j] - prime_indices[i])
    return max_distance

def minLength(s):
    s = sorted(s)
    n = len(s)
    i = 0
    j = 1
    while j < n:
        if s[i] != s[j]:
            i += 1
        j += 1
    return n - i

def sum_of_digit_differences(nums):
    num_str = [str(num) for num in nums]
    total_diff = 0
    for i in range(len(num_str)):
        for j in range(i+1, len(num_str)):
            total_diff += sum(1 for a, b in zip(num_str[i], num_str[j]) if a != b)
    return total_diff

def powerful_array(n):
    res = []
    while n:
        res.append(n & -n)
        n >>= 1
    return sorted(res)

def get_big_nums(n):
    big_nums = {}
    i = 1
    while True:
        powerful_array = powerful_array(i)
        if i not in big_nums:
            big_nums[i] = powerful_array
        else:
            big_nums[i] = big_nums[i] + powerful_array
        i += 1
        if i > n:
            break
    return big_nums

def product_mod(queries, big_nums, mod):
    answer = []
    for query in queries:
        from_i, to_i, mod_i = query
        product = 1
        for i in range(from_i, to_i + 1):
            product = (product * big_nums[i]) % mod_i
        answer.append(product)
    return answer

def xor_twice(nums):
    xor_result = 0
    for num in nums:
        if nums.count(num) == 2:
            xor_result ^= num
    return xor_result
